reference_solution:
def solveNQueens(n):
    res, board = [], []
    cols, d1, d2 = set(), set(), set()
    def bt(r):
        if r == n:
            res.append(["".join("Q" if c == q else "." for c in range(n)) for q in board])
            return
        for c in range(n):
            if c in cols or (r - c) in d1 or (r + c) in d2:
                continue
            cols.add(c); d1.add(r - c); d2.add(r + c); board.append(c)
            bt(r + 1)
            board.pop(); cols.remove(c); d1.remove(r - c); d2.remove(r + c)
    bt(0)
    return res

