import itertools
def solveNQueens(n):
    res = []
    for perm in itertools.permutations(range(n)):
        if all(abs(perm[i] - perm[j]) != j - i for i in range(n) for j in range(i + 1, n)):
            res.append(["".join("Q" if c == q else "." for c in range(n)) for q in perm])
    return res

